from typing import Sequence

class MockCrontabParser:
    def __init__(self, min_, max_):
        self.min_ = min_
        self.max_ = max_

    def _expand_number(self, s: str) -> int:
        return int(s)

    def _expand_range(self, toks: Sequence[str]) -> list[int]:
        fr = self._expand_number(toks[0])
        if len(toks) > 1:
            to = self._expand_number(toks[1])
            if to < fr:  # Wrap around max_ if necessary
                return (list(range(fr, self.min_ + self.max_)) +
                        list(range(self.min_, to + 1)))
            return list(range(fr, to + 1))
        return [fr]

# For hour fields in a crontab, the valid range is 0-23.
# A wrap-around range like "22-2" should expand to [22, 23, 0, 1, 2].
# The parser is initialized with min_=0, max_=23 for hours.
parser = MockCrontabParser(min_=0, max_=23)

# The buggy logic calculates the upper part of the range as
# range(22, 0 + 23), which is range(22, 23), producing only [22].
# The value 23 is incorrectly omitted.
result = parser._expand_range(['22', '2'])

if result == [22, 0, 1, 2]:
    print("CONFIRMED")
else:
    print("REFUTED")

