        self._db_args = {"database_module": MockDbModule()}
        self._db_kwargs = {}
        self._db = self._db_args["database_module"].connect(**self._db_kwargs)
        self._db.autocommit(True)

    def close(self):
        if self._db is not None:
            self._db.close()
            self._db = None

    def reconnect(self):
        self.close()
        self._db = self._db_args["database_module"].connect(**self._db_kwargs)
        self._db.autocommit(True)

    def _cursor(self):
        return self._db.cursor()

