# This snippet models the interaction between flask.url_for and Blueprint.url_for
# when an endpoint with a dot has been registered via a blueprint.

# Represents the application and its registered blueprints
class App:
    def __init__(self):
        self.blueprints = {}

# Represents a blueprint
class Blueprint:
    def __init__(self, name):
        self.name = name

    # Simplified Blueprint.url_for
    def url_for(self, endpoint, **values):
        # This is the crucial part of the blueprint's URL generation logic,
        # which prepends the blueprint name to the endpoint.
        return url_for(self.name + '.' + endpoint, **values)

# Global application object and a mock url_for function
app = App()

# Simplified flask.helpers.url_for
def url_for(endpoint, **values):
    # This logic splits the endpoint to find the blueprint
    if '.' in endpoint:
        blueprint_name, endpoint_name = endpoint.split('.', 1)
        if blueprint_name in app.blueprints:
            # It then delegates to the blueprint's url_for, causing recursion
            # if endpoint_name itself contains a dot.
            return app.blueprints[blueprint_name].url_for(endpoint_name, **values)
    # Base case for non-blueprint or resolved URLs (not reached in the bug)
    return f"/url/for/{endpoint}"

def run_test():
    # Setup: Create a blueprint and register it.
    # The old add_url_rule allowed registering an endpoint like 'a.b',
    # leading to this state.
    bp = Blueprint('my_bp')
    app.blueprints['my_bp'] = bp

    try:
        # Attempt to build a URL for the endpoint 'a.b' on blueprint 'my_bp'.
        # The full endpoint string is 'my_bp.a.b'.
        # flask.url_for('my_bp.a.b') splits it into 'my_bp' and 'a.b',
        # then calls my_bp.url_for('a.b').
        # my_bp.url_for('a.b') calls flask.url_for('my_bp.a.b') again, causing a loop.
        url_for('my_bp.a.b')
        print("REFUTED")
    except RecursionError:
        print("CONFIRMED")
    except Exception:
        print("REFUTED")

run_test()

