import re

# This function mimics w3lib.encoding.resolve_encoding's behavior
# for the relevant case where it canonicalizes iso-8859-1.
def resolve_encoding(encoding_alias):
    if encoding_alias.lower() == 'iso-8859-1':
        return 'cp1252'
    return encoding_alias

class MockTextResponse:
    """A mock response class that mimics Scrapy's encoding detection logic."""
    def __init__(self, headers=None):
        self._headers = headers or {}
        self._encoding = None  # Cache for the public .encoding property

    def _headers_encoding(self):
        content_type = self._headers.get("Content-type", [None])[0]
        if not content_type:
            return None
        match = re.search(r"charset=([\w-]+)", content_type, re.I)
        return resolve_encoding(match.group(1)) if match else None

    def _declared_encoding(self):
        return self._headers_encoding()

    def _get_encoding(self):
        # This simplified logic follows Scrapy's TextResponse for this case
        return self._declared_encoding()

    @property
    def encoding(self):
        if self._encoding is None:
            self._encoding = self._get_encoding()
        return self._encoding

# In the test, r3 is created with an 'iso-8859-1' header.
r3 = MockTextResponse(headers={"Content-type": ["text/html; charset=iso-8859-1"]})

# The test was updated to assert the *declared* encoding is now 'cp1252'.
# This is symbol_a's behavior.
declared_encoding_is_cp1252 = r3._declared_encoding() == 'cp1252'

# As a consequence, the final public `encoding` property also becomes 'cp1252'.
final_encoding_is_cp1252 = r3.encoding == 'cp1252'

# However, the test still contains a later assertion (symbol_b) that expects
# the final encoding to be 'iso-8859-1'. This old expectation is now incorrect.
old_assertion_is_invalid = final_encoding_is_cp1252

if old_assertion_is_invalid:
